// ============================================================================
//  flash_bank.v - 16K x 16 true dual-port RAM built from 16 Gowin DPB blocks
//  (1K x 16 each). Explicit primitives so every toolchain maps it to exactly
//  16 BSRAMs. Read latency is one cycle on both ports (READ_MODE bypass).
//
//  Block 15 of each bank holds flash words 0x7800-0x7FFF (byte 0xF000, the
//  AVR boot section) and is initialised with the Uzebox bootloader from
//  bootloader_init.vh (generated by tools/hex2mem.py --gowin-init), unless
//  UZETANG_NO_BOOTLOADER is defined.
//
//  Copyright (C) 2026 UzeTang contributors - GPL v3 or later.
// ============================================================================
`default_nettype none
`ifndef UZETANG_NO_BOOTLOADER
`include "bootloader_init.vh"
`endif
module flash_bank #(
    parameter BANK = 0          // 0: even words, 1: odd words
)(
    input  wire        clk,
    input  wire        cea,
    input  wire [13:0] addra,
    output wire [15:0] qa,
    input  wire        ceb,
    input  wire [13:0] addrb,
    input  wire        web,
    input  wire [15:0] db,
    output wire [15:0] qb
);
    wire [15:0] doa [0:15];
    wire [15:0] dob [0:15];
    reg  [3:0]  sela, selb;
    always @(posedge clk) begin
        if (cea) sela <= addra[13:10];
        if (ceb) selb <= addrb[13:10];
    end
    assign qa = doa[sela];
    assign qb = dob[selb];

    genvar i;
    generate for (i = 0; i < 15; i = i + 1) begin : blk
        DPB #(
            .READ_MODE0(1'b0), .READ_MODE1(1'b0),
            .WRITE_MODE0(2'b00), .WRITE_MODE1(2'b00),
            .BIT_WIDTH_0(16), .BIT_WIDTH_1(16),
            .BLK_SEL_0(3'b000), .BLK_SEL_1(3'b000),
            .RESET_MODE("SYNC")
        ) ram (
            .DOA(doa[i]), .DOB(dob[i]),
            .CLKA(clk), .OCEA(1'b1), .CEA(cea), .RESETA(1'b0), .WREA(1'b0),
            .CLKB(clk), .OCEB(1'b1), .CEB(ceb), .RESETB(1'b0),
            .WREB(web && addrb[13:10] == i),
            .BLKSELA(3'b000), .BLKSELB(3'b000),
            .ADA({addra[9:0], 4'b0011}), .DIA(16'd0),
            .ADB({addrb[9:0], 4'b0011}), .DIB(db)
        );
    end endgenerate

    // block 15: boot section
`ifndef UZETANG_NO_BOOTLOADER
    DPB #(
            .READ_MODE0(1'b0), .READ_MODE1(1'b0),
            .WRITE_MODE0(2'b00), .WRITE_MODE1(2'b00),
            .BIT_WIDTH_0(16), .BIT_WIDTH_1(16),
            .BLK_SEL_0(3'b000), .BLK_SEL_1(3'b000),
            .RESET_MODE("SYNC"),
                .INIT_RAM_00(BANK ? `BOOTINIT_O_00 : `BOOTINIT_E_00),
                .INIT_RAM_01(BANK ? `BOOTINIT_O_01 : `BOOTINIT_E_01),
                .INIT_RAM_02(BANK ? `BOOTINIT_O_02 : `BOOTINIT_E_02),
                .INIT_RAM_03(BANK ? `BOOTINIT_O_03 : `BOOTINIT_E_03),
                .INIT_RAM_04(BANK ? `BOOTINIT_O_04 : `BOOTINIT_E_04),
                .INIT_RAM_05(BANK ? `BOOTINIT_O_05 : `BOOTINIT_E_05),
                .INIT_RAM_06(BANK ? `BOOTINIT_O_06 : `BOOTINIT_E_06),
                .INIT_RAM_07(BANK ? `BOOTINIT_O_07 : `BOOTINIT_E_07),
                .INIT_RAM_08(BANK ? `BOOTINIT_O_08 : `BOOTINIT_E_08),
                .INIT_RAM_09(BANK ? `BOOTINIT_O_09 : `BOOTINIT_E_09),
                .INIT_RAM_0A(BANK ? `BOOTINIT_O_0A : `BOOTINIT_E_0A),
                .INIT_RAM_0B(BANK ? `BOOTINIT_O_0B : `BOOTINIT_E_0B),
                .INIT_RAM_0C(BANK ? `BOOTINIT_O_0C : `BOOTINIT_E_0C),
                .INIT_RAM_0D(BANK ? `BOOTINIT_O_0D : `BOOTINIT_E_0D),
                .INIT_RAM_0E(BANK ? `BOOTINIT_O_0E : `BOOTINIT_E_0E),
                .INIT_RAM_0F(BANK ? `BOOTINIT_O_0F : `BOOTINIT_E_0F),
                .INIT_RAM_10(BANK ? `BOOTINIT_O_10 : `BOOTINIT_E_10),
                .INIT_RAM_11(BANK ? `BOOTINIT_O_11 : `BOOTINIT_E_11),
                .INIT_RAM_12(BANK ? `BOOTINIT_O_12 : `BOOTINIT_E_12),
                .INIT_RAM_13(BANK ? `BOOTINIT_O_13 : `BOOTINIT_E_13),
                .INIT_RAM_14(BANK ? `BOOTINIT_O_14 : `BOOTINIT_E_14),
                .INIT_RAM_15(BANK ? `BOOTINIT_O_15 : `BOOTINIT_E_15),
                .INIT_RAM_16(BANK ? `BOOTINIT_O_16 : `BOOTINIT_E_16),
                .INIT_RAM_17(BANK ? `BOOTINIT_O_17 : `BOOTINIT_E_17),
                .INIT_RAM_18(BANK ? `BOOTINIT_O_18 : `BOOTINIT_E_18),
                .INIT_RAM_19(BANK ? `BOOTINIT_O_19 : `BOOTINIT_E_19),
                .INIT_RAM_1A(BANK ? `BOOTINIT_O_1A : `BOOTINIT_E_1A),
                .INIT_RAM_1B(BANK ? `BOOTINIT_O_1B : `BOOTINIT_E_1B),
                .INIT_RAM_1C(BANK ? `BOOTINIT_O_1C : `BOOTINIT_E_1C),
                .INIT_RAM_1D(BANK ? `BOOTINIT_O_1D : `BOOTINIT_E_1D),
                .INIT_RAM_1E(BANK ? `BOOTINIT_O_1E : `BOOTINIT_E_1E),
                .INIT_RAM_1F(BANK ? `BOOTINIT_O_1F : `BOOTINIT_E_1F),
                .INIT_RAM_20(BANK ? `BOOTINIT_O_20 : `BOOTINIT_E_20),
                .INIT_RAM_21(BANK ? `BOOTINIT_O_21 : `BOOTINIT_E_21),
                .INIT_RAM_22(BANK ? `BOOTINIT_O_22 : `BOOTINIT_E_22),
                .INIT_RAM_23(BANK ? `BOOTINIT_O_23 : `BOOTINIT_E_23),
                .INIT_RAM_24(BANK ? `BOOTINIT_O_24 : `BOOTINIT_E_24),
                .INIT_RAM_25(BANK ? `BOOTINIT_O_25 : `BOOTINIT_E_25),
                .INIT_RAM_26(BANK ? `BOOTINIT_O_26 : `BOOTINIT_E_26),
                .INIT_RAM_27(BANK ? `BOOTINIT_O_27 : `BOOTINIT_E_27),
                .INIT_RAM_28(BANK ? `BOOTINIT_O_28 : `BOOTINIT_E_28),
                .INIT_RAM_29(BANK ? `BOOTINIT_O_29 : `BOOTINIT_E_29),
                .INIT_RAM_2A(BANK ? `BOOTINIT_O_2A : `BOOTINIT_E_2A),
                .INIT_RAM_2B(BANK ? `BOOTINIT_O_2B : `BOOTINIT_E_2B),
                .INIT_RAM_2C(BANK ? `BOOTINIT_O_2C : `BOOTINIT_E_2C),
                .INIT_RAM_2D(BANK ? `BOOTINIT_O_2D : `BOOTINIT_E_2D),
                .INIT_RAM_2E(BANK ? `BOOTINIT_O_2E : `BOOTINIT_E_2E),
                .INIT_RAM_2F(BANK ? `BOOTINIT_O_2F : `BOOTINIT_E_2F),
                .INIT_RAM_30(BANK ? `BOOTINIT_O_30 : `BOOTINIT_E_30),
                .INIT_RAM_31(BANK ? `BOOTINIT_O_31 : `BOOTINIT_E_31),
                .INIT_RAM_32(BANK ? `BOOTINIT_O_32 : `BOOTINIT_E_32),
                .INIT_RAM_33(BANK ? `BOOTINIT_O_33 : `BOOTINIT_E_33),
                .INIT_RAM_34(BANK ? `BOOTINIT_O_34 : `BOOTINIT_E_34),
                .INIT_RAM_35(BANK ? `BOOTINIT_O_35 : `BOOTINIT_E_35),
                .INIT_RAM_36(BANK ? `BOOTINIT_O_36 : `BOOTINIT_E_36),
                .INIT_RAM_37(BANK ? `BOOTINIT_O_37 : `BOOTINIT_E_37),
                .INIT_RAM_38(BANK ? `BOOTINIT_O_38 : `BOOTINIT_E_38),
                .INIT_RAM_39(BANK ? `BOOTINIT_O_39 : `BOOTINIT_E_39),
                .INIT_RAM_3A(BANK ? `BOOTINIT_O_3A : `BOOTINIT_E_3A),
                .INIT_RAM_3B(BANK ? `BOOTINIT_O_3B : `BOOTINIT_E_3B),
                .INIT_RAM_3C(BANK ? `BOOTINIT_O_3C : `BOOTINIT_E_3C),
                .INIT_RAM_3D(BANK ? `BOOTINIT_O_3D : `BOOTINIT_E_3D),
                .INIT_RAM_3E(BANK ? `BOOTINIT_O_3E : `BOOTINIT_E_3E),
                .INIT_RAM_3F(BANK ? `BOOTINIT_O_3F : `BOOTINIT_E_3F)
    ) boot (
`else
    DPB #(
            .READ_MODE0(1'b0), .READ_MODE1(1'b0),
            .WRITE_MODE0(2'b00), .WRITE_MODE1(2'b00),
            .BIT_WIDTH_0(16), .BIT_WIDTH_1(16),
            .BLK_SEL_0(3'b000), .BLK_SEL_1(3'b000),
            .RESET_MODE("SYNC")
    ) boot (
`endif
            .DOA(doa[15]), .DOB(dob[15]),
            .CLKA(clk), .OCEA(1'b1), .CEA(cea), .RESETA(1'b0), .WREA(1'b0),
            .CLKB(clk), .OCEB(1'b1), .CEB(ceb), .RESETB(1'b0),
            .WREB(web && addrb[13:10] == 4'd15),
            .BLKSELA(3'b000), .BLKSELB(3'b000),
            .ADA({addra[9:0], 4'b0011}), .DIA(16'd0),
            .ADB({addrb[9:0], 4'b0011}), .DIB(db)
    );
endmodule

// ============================================================================
//  eeprom_ram.v - 2K x 8 EEPROM storage: one Gowin SP block, erased (0xFF)
// ============================================================================
module eeprom_ram (
    input  wire        clk,
    input  wire        ce,
    input  wire [10:0] addr,
    input  wire        we,
    input  wire [7:0]  d,
    output wire [7:0]  q
);
    wire [31:0] dout;
    assign q = dout[7:0];
    SP #(
        .READ_MODE(1'b0), .WRITE_MODE(2'b00), .BIT_WIDTH(8),
        .BLK_SEL(3'b000), .RESET_MODE("SYNC"),
        .INIT_RAM_00({256{1'b1}}),
        .INIT_RAM_01({256{1'b1}}),
        .INIT_RAM_02({256{1'b1}}),
        .INIT_RAM_03({256{1'b1}}),
        .INIT_RAM_04({256{1'b1}}),
        .INIT_RAM_05({256{1'b1}}),
        .INIT_RAM_06({256{1'b1}}),
        .INIT_RAM_07({256{1'b1}}),
        .INIT_RAM_08({256{1'b1}}),
        .INIT_RAM_09({256{1'b1}}),
        .INIT_RAM_0A({256{1'b1}}),
        .INIT_RAM_0B({256{1'b1}}),
        .INIT_RAM_0C({256{1'b1}}),
        .INIT_RAM_0D({256{1'b1}}),
        .INIT_RAM_0E({256{1'b1}}),
        .INIT_RAM_0F({256{1'b1}}),
        .INIT_RAM_10({256{1'b1}}),
        .INIT_RAM_11({256{1'b1}}),
        .INIT_RAM_12({256{1'b1}}),
        .INIT_RAM_13({256{1'b1}}),
        .INIT_RAM_14({256{1'b1}}),
        .INIT_RAM_15({256{1'b1}}),
        .INIT_RAM_16({256{1'b1}}),
        .INIT_RAM_17({256{1'b1}}),
        .INIT_RAM_18({256{1'b1}}),
        .INIT_RAM_19({256{1'b1}}),
        .INIT_RAM_1A({256{1'b1}}),
        .INIT_RAM_1B({256{1'b1}}),
        .INIT_RAM_1C({256{1'b1}}),
        .INIT_RAM_1D({256{1'b1}}),
        .INIT_RAM_1E({256{1'b1}}),
        .INIT_RAM_1F({256{1'b1}}),
        .INIT_RAM_20({256{1'b1}}),
        .INIT_RAM_21({256{1'b1}}),
        .INIT_RAM_22({256{1'b1}}),
        .INIT_RAM_23({256{1'b1}}),
        .INIT_RAM_24({256{1'b1}}),
        .INIT_RAM_25({256{1'b1}}),
        .INIT_RAM_26({256{1'b1}}),
        .INIT_RAM_27({256{1'b1}}),
        .INIT_RAM_28({256{1'b1}}),
        .INIT_RAM_29({256{1'b1}}),
        .INIT_RAM_2A({256{1'b1}}),
        .INIT_RAM_2B({256{1'b1}}),
        .INIT_RAM_2C({256{1'b1}}),
        .INIT_RAM_2D({256{1'b1}}),
        .INIT_RAM_2E({256{1'b1}}),
        .INIT_RAM_2F({256{1'b1}}),
        .INIT_RAM_30({256{1'b1}}),
        .INIT_RAM_31({256{1'b1}}),
        .INIT_RAM_32({256{1'b1}}),
        .INIT_RAM_33({256{1'b1}}),
        .INIT_RAM_34({256{1'b1}}),
        .INIT_RAM_35({256{1'b1}}),
        .INIT_RAM_36({256{1'b1}}),
        .INIT_RAM_37({256{1'b1}}),
        .INIT_RAM_38({256{1'b1}}),
        .INIT_RAM_39({256{1'b1}}),
        .INIT_RAM_3A({256{1'b1}}),
        .INIT_RAM_3B({256{1'b1}}),
        .INIT_RAM_3C({256{1'b1}}),
        .INIT_RAM_3D({256{1'b1}}),
        .INIT_RAM_3E({256{1'b1}}),
        .INIT_RAM_3F({256{1'b1}})
    ) ram (
        .DO(dout), .DI({24'd0, d}), .BLKSEL(3'b000), .AD({addr, 3'b000}),
        .WRE(we), .CLK(clk), .CE(ce), .OCE(1'b1), .RESET(1'b0)
    );
endmodule
// ============================================================================
//  sram_4k - AVR data SRAM, 4K x 8 from two Gowin SP blocks (2K x 8 each)
// ============================================================================
module sram_4k (
    input  wire        clk,
    input  wire        ce,
    input  wire [11:0] addr,
    input  wire        we,
    input  wire [7:0]  d,
    output wire [7:0]  q
);
    wire [31:0] d0, d1;
    reg         hi;
    always @(posedge clk) if (ce) hi <= addr[11];
    assign q = hi ? d1[7:0] : d0[7:0];
    SP #(.READ_MODE(1'b0), .WRITE_MODE(2'b00), .BIT_WIDTH(8), .BLK_SEL(3'b000), .RESET_MODE("SYNC")) lo_ram (
        .DO(d0), .DI({24'd0, d}), .BLKSEL(3'b000), .AD({addr[10:0], 3'b000}),
        .WRE(we & ~addr[11]), .CLK(clk), .CE(ce), .OCE(1'b1), .RESET(1'b0));
    SP #(.READ_MODE(1'b0), .WRITE_MODE(2'b00), .BIT_WIDTH(8), .BLK_SEL(3'b000), .RESET_MODE("SYNC")) hi_ram (
        .DO(d1), .DI({24'd0, d}), .BLKSEL(3'b000), .AD({addr[10:0], 3'b000}),
        .WRE(we & addr[11]), .CLK(clk), .CE(ce), .OCE(1'b1), .RESET(1'b0));
endmodule
`default_nettype wire
